/* Numera Academy — Lição em tela cheia: ideia, simulação passo a passo e questões de prática.
   Parte da interface (antes, app.js). Os arquivos de js/site e js/paginas são scripts clássicos que
   compartilham as mesmas variáveis; a ordem de carregamento está no index.html. */
'use strict';
/* ---------- Lição em tela cheia ---------- */
function introScreens(){const m=method(s.method),d=C.DEEP[m.id];return [
 {eyebrow:'A ideia central',title:m.short,body:`<p class="lead">${m.concept}</p><div class="formula big">${safe(m.formula)}</div>`},
 {eyebrow:'Antes de começar',title:'Quais condições precisam valer?',body:`<p class="lead">${d.requires}</p><div class="callout"><strong>Dica</strong><p>${safe(m.tip)}</p></div>`},
 {eyebrow:'Como executar',title:'O procedimento, passo a passo',body:`<ol class="numbered">${d.steps.map(t=>`<li>${safe(t)}</li>`).join('')}</ol>`},
 {eyebrow:'Critério de parada',title:'Quando parar?',body:`<p class="lead">${d.stop}</p>`},
 ...(d.professora?[{eyebrow:'Como a professora resolve',title:d.professora.titulo,body:professorExample(d)}]:[]),
 {eyebrow:'Olhar crítico',title:'O que pode dar errado?',body:`<p class="lead">${d.trap}</p><div class="example-box"><span class="eyebrow">Exemplo</span><p>${safe(m.example)}</p></div>`},
 {eyebrow:'Do raciocínio ao algoritmo',title:'Em pseudocódigo',body:`<pre class="pseudocode" tabindex="0" aria-label="Pseudocódigo">${safe(d.pseudo)}</pre>`},
 {eyebrow:'Aulas em vídeo',title:'Quer ouvir alguém explicando?',body:`<p class="lead">Escolhemos aulas de ${m.title} de professores de Cálculo Numérico. Assista e depois volte para a simulação: ver o método rodando passo a passo ajuda a fixar o que a aula explicou.</p>${videoList(m.id,'in-player')}`}];}
/* Exemplo dos slides da professora, refeito pelo passo-a-passo.js: mesma tabela, mesmas colunas e o mesmo critério de parada. */
function professorRun(d){const PP=window.NumeraPassos,c=d.professora.chamada;return c.metodo==='gauss'?PP.gauss(c):c.metodo==='seidel'?PP.seidel(c):PP[c.metodo](c);}
const PSUB=t=>String(t).replace(/x(\d)/g,(_,n)=>'x'+'₀₁₂₃₄₅₆₇₈₉'[n]);
function passosTable(cols,rows,hl=-1){return `<div class="pp-table-wrap"><table class="pp-table"><thead><tr>${cols.map(c=>`<th scope="col">${safe(c)}</th>`).join('')}</tr></thead><tbody>${rows.map((r,k)=>`<tr class="${k===hl?'on':''}">${r.map(v=>`<td>${safe(v)}</td>`).join('')}</tr>`).join('')}</tbody></table></div>`;}
function ppMatrix(mat,label){const PP=window.NumeraPassos;return `<div class="matrix-wrap"><table class="matrix" aria-label="${safe(label)}"><caption>${safe(label)}</caption><tbody>${mat.map(r=>`<tr>${r.map((x,i)=>`<td class="${i===r.length-1?'rhs':''}">${safe(PP.frac(x)||PP.fmt(x))}</td>`).join('')}</tr>`).join('')}</tbody></table></div>`;}
function professorExample(d){const PP=window.NumeraPassos;if(!PP)return '';const pr=d.professora;let r;try{r=professorRun(d);}catch(e){return `<p class="fine">${safe(e.message)}</p>`;}
 let body='';
 if(pr.chamada.metodo==='gauss'){body=r.etapas.map(e=>`<div class="pp-stage"><h3>${safe(e.titulo)}</h3>${e.k?`<p>Pivô da ${e.k}ª etapa: ${safe(PP.frac(e.pivo)||PP.fmt(e.pivo))}${e.troca?` · troca de linhas (${safe(e.motivoTroca)})`:''}</p><ul>${e.multiplicadores.map(m=>`<li>m${PP.sub(m.i+1)}${PP.sub(m.k+1)} = ${safe(PP.frac(m.m)||PP.fmt(m.m))}</li>`).join('')}${e.operacoes.map(o=>`<li>${safe(o)}</li>`).join('')}</ul>`:''}${ppMatrix(e.matriz,`[A${PP.sup('('+e.k+')')} | B${PP.sup('('+e.k+')')}]`)}</div>`).join('')+`<div class="pp-stage"><h3>Substituição regressiva</h3><ul>${r.substituicao.map(t=>`<li>${safe(t.texto)}</li>`).join('')}</ul></div>`;}
 else{const t=PP.tabela(r);body=passosTable(t.colunas,t.linhas,t.linhas.length-1);}
 return `<p class="lead">${safe(pr.texto)}</p>${body}<div class="callout"><strong>Conclusão</strong><p>${safe(pr.conclusao)}</p></div><p class="fine">Tabela refeita pelo Numera com os mesmos dados dos slides${r.parada?`. Parada: ${safe(r.parada)}`:''}.</p>`;}
function playerTop(segs,label,closeAct,closeAttrs){return `<div class="player-top"><button type="button" class="icon-btn" data-act="${closeAct}" ${closeAttrs} aria-label="Fechar e voltar">${icon('close')}</button><div class="player-progress" role="img" aria-label="${safe(label)}">${segs.map(c=>`<i class="${c}"></i>`).join('')}</div><span class="player-meta">${comboPips()}${coinChip()}<span class="xp-meta">✦ ${p.xp}</span></span></div>`;}
function levelSegs(){const l=s.q<4?0:s.q<8?1:2;return [0,1,2,3].map(j=>{const i=l*4+j;return p.completed[`c:${s.method}:${i}`]?'done':i===s.q?'current':'';});}
function introPlayer(){const sc=introScreens(),i=Math.min(s.introStep,sc.length-1),cur=sc[i],last=i===sc.length-1;return `<div class="player">${playerTop(sc.map((_,j)=>j<i?'done':j===i?'current':''),`Tela ${i+1} de ${sc.length}`,'course-tab','data-id="learn"')}<div class="player-body"><div class="player-col"><span class="eyebrow">${cur.eyebrow}</span><h1 class="display">${cur.title}</h1>${cur.body}</div></div><div class="player-bar"><div class="player-bar-inner"><span class="bar-count">${i+1} de ${sc.length}</span><div class="answer-actions">${i?btn('Voltar','intro-prev','ghost'):''}${btn(last?'Ver o método em ação '+icon('arrow'):'Continuar','intro-next','primary')}</div></div></div></div>`;}
/* Simulação: roda o exemplo da professora (passo-a-passo.js) e monta um registro por linha da tabela dela.
   Cada registro traz os campos que os gráficos usam (a, b, tangente, secante) e uma explicação na notação dos slides. */
function simulationResult(){const m=s.method,d=C.DEEP[m],PP=window.NumeraPassos,o={tolerance:1e-8,maxIterations:80};
 if(!PP||!d.professora){if(d.system){const {A,b}=M.parseSystem(d.system);return m==='gauss'?M.gauss(A,b,o):M.seidel(A,b,A.map(()=>0),o);}const fn=M.parseFunction(d.example);return m==='bisection'?M.bisection(fn,d.a,d.b,o):m==='falseposition'?M.falsePosition(fn,d.a,d.b,o):m==='fixedpoint'?M.fixedPoint(M.parseFunction(d.g),d.x0,o):m==='newton'?M.newton(fn,d.x0,o):M.secant(fn,d.x0,d.x1,o);}
 const c=d.professora.chamada,r=professorRun(d),F=PP.fmt,S=PP.sub,its=[];
 if(c.metodo==='gauss'){for(const e of r.etapas)its.push({i:e.k,matrix:e.matriz,detail:e.k===0?'Etapa zero: matriz ampliada [A⁽⁰⁾ | B⁽⁰⁾]. O pivô da 1ª etapa é a₁₁⁽⁰⁾ = '+(PP.frac(e.pivo)||F(e.pivo))+' e a 1ª linha é a equação pivô.':`Etapa ${e.k}: pivô a${S(e.k)}${S(e.k)}${PP.sup('('+(e.k-1)+')')} = ${PP.frac(e.pivo)||F(e.pivo)}. `+e.multiplicadores.map(q=>`m${S(q.i+1)}${S(q.k+1)} = ${PP.frac(q.m)||F(q.m)}`).join(' e ')+'. '+e.operacoes.join('; ')+'.',label:`[A${PP.sup('('+e.k+')')} | B${PP.sup('('+e.k+')')}]`});
  its.push({i:r.etapas.length,matrix:r.triangular,detail:'Substituição regressiva: '+r.substituicao.map(t=>t.texto).join('; ')+'. Prova real: substitua X* nas equações originais.',label:'Sistema triangular superior'});return {method:'gauss',root:r.solucao,iterations:its,converged:true};}
 if(c.metodo==='seidel'){for(const l of r.linhas)its.push({i:l.k,x:l.x,detail:l.k===0?'Vetor inicial X⁽⁰⁾.':`Iteração ${l.k}: X${PP.sup('('+l.k+')')} = (${l.x.map(v=>F(v)).join('; ')}). Cada xᵢ${PP.sup('('+l.k+')')} já usa os valores atualizados nesta mesma iteração. Erro relativo d${PP.sup('('+l.k+')')} = máx|Δx| / máx|x| = ${F(l.erro)}.`});return {method:'seidel',root:r.solucao,iterations:its,converged:true};}
 const f=c.f?PP.fn(c.f):null;
 if(c.metodo==='bissecao'||c.metodo==='falsaPosicao'){const nome=c.metodo==='bissecao'?'O valor médio':'A média ponderada';for(const l of r.linhas)its.push({i:l.i,x:l.x,fx:l.fx,a:l.a,b:l.b,fa:l.fa,fb:l.fb,kept:c.metodo==='falsaPosicao'?l.lado:undefined,error:l.erro,detail:`i = ${l.i}: a = ${F(l.a)} e b = ${F(l.b)}. ${nome} é x${S(l.i)} = ${F(l.x)} e f(x${S(l.i)}) = ${F(l.fx)} (${PP.sinal(l.fx)}). Como f(a)·f(x${S(l.i)}) ${l.lado==='inferior'?'< 0, a raiz está no subintervalo inferior: b recebe x'+S(l.i):l.lado==='superior'?'> 0, a raiz está no subintervalo superior: a recebe x'+S(l.i):'= 0, x'+S(l.i)+' é a raiz'}.${l.erro===null?'':` Erro estimado: ${F(l.erro)}${c.criterio==='percentual'?'%':''}.`}`});return {method:m,root:r.raiz,iterations:its,converged:true,interval:{a:c.a,b:c.b}};}
 if(c.metodo==='pontoFixo'){for(const l of r.linhas)its.push({i:l.i,x:l.x,gx:l.novo,fx:l.novo-l.x,detail:`i = ${l.i}: x${S(l.i+1)} = g(x${S(l.i)}) = ${F(l.novo)}. Eᵣ% = ${F(l.erro)}%.`});return {method:m,root:r.raiz,iterations:its,converged:true};}
 if(c.metodo==='newton'){its.push({i:0,x:Number(c.x0),fx:f(Number(c.x0)),detail:`Aproximação inicial x₀ = ${F(Number(c.x0))}.`});for(const l of r.linhas)its.push({i:l.i+1,x:l.novo,fx:f(l.novo),previous:l.x,derivative:l.dfx,detail:`i = ${l.i}: f(x${S(l.i)}) = ${F(l.fx)} e f′(x${S(l.i)}) = ${F(l.dfx)}, então x${S(l.i+1)} = ${F(l.x)} − (${F(l.fx)})/(${F(l.dfx)}) = ${F(l.novo)}. Eᵣ% = ${F(l.erro)}%.`});return {method:m,root:r.raiz,iterations:its,converged:true};}
 its.push({i:0,x:Number(c.x0),fx:f(Number(c.x0)),detail:`Primeira aproximação x₀ = ${F(Number(c.x0))}.`},{i:1,x:Number(c.x1),fx:f(Number(c.x1)),detail:`Segunda aproximação x₁ = ${F(Number(c.x1))}: a Secante precisa de duas.`});
 for(const l of r.linhas)its.push({i:l.i+1,x:l.novo,fx:f(l.novo),x0:l.ant,x1:l.x,f0:l.fAnt,f1:l.fx,detail:`i = ${l.i}: xᵢ₋₁ = ${F(l.ant)}, xᵢ = ${F(l.x)}, f(xᵢ₋₁) = ${F(l.fAnt)} e f(xᵢ) = ${F(l.fx)}. xᵢ₊₁ = xᵢ − f(xᵢ)(xᵢ − xᵢ₋₁)/(f(xᵢ) − f(xᵢ₋₁)) = ${F(l.novo)}. ER% = ${F(l.erro)}%.`});
 return {method:m,root:r.raiz,iterations:its,converged:true};}
function matrix(mat){return `<div class="matrix-wrap"><table class="matrix" aria-label="Matriz ampliada"><tbody>${mat.map(r=>`<tr>${r.map((x,i)=>`<td class="${i===r.length-1?'rhs':''}">${num(x)}</td>`).join('')}</tr>`).join('')}</tbody></table></div>`;}
function simulation(){const r=simulationResult(),d=C.DEEP[s.method],i=Math.min(s.sim,r.iterations.length-1),row=r.iterations[i],m=s.method;
 const stage=d.system?`<pre class="formula">${safe(PSUB(d.system))}</pre>${row.matrix?(window.NumeraPassos?ppMatrix(row.matrix,row.label||'Matriz ampliada'):matrix(row.matrix)):`<div class="vector">${row.x.map((v,k)=>`<span>x${k+1}<b>${num(v)}</b></span>`).join('')}</div>`}`:m==='fixedpoint'?cobweb(M.parseFunction(d.g),r,row):graph(M.parseFunction(d.example),r,d,row);
 const info=typeof row.x==='number'?`<div class="formula">x ≈ ${num(row.x)} · ${m==='fixedpoint'?'|x − g(x)|':'|f(x)|'} = ${num(Math.abs(row.fx))}</div>`:row.residual!==undefined?`<div class="formula">resíduo máximo = ${num(row.residual)}</div>`:'';
 const note=m==='falseposition'?'A faixa destacada é o intervalo [a, b] desta iteração e a reta liga (a, f(a)) a (b, f(b)): o novo ponto é onde ela corta o eixo x.':m==='fixedpoint'?`Diagrama em teia: a curva é y = g(x) e a diagonal é y = x. Cada degrau sobe até g e volta à diagonal, que transforma g(xᵢ) no próximo xᵢ₊₁ (aqui g(x) = ${safe(d.g)}).`:m==='bisection'?'A faixa destacada é o intervalo [a, b] desta iteração; o ponto é o valor médio xᵢ.':m==='newton'?'A reta tracejada é a tangente em xᵢ, prolongada até o eixo x.':m==='secant'?'A reta tracejada liga os dois pontos anteriores, xᵢ₋₁ e xᵢ.':m==='gauss'?'Os índices entre parênteses dizem a etapa: [A⁽ᵏ⁾ | B⁽ᵏ⁾] é a matriz ampliada depois da etapa k.':'Confira a atualização de cada linha e a ordem em que os valores são usados.';
 return `<div class="player">${playerTop(r.iterations.map((_,j)=>j<i?'done':j===i?'current':''),`Registro ${i+1} de ${r.iterations.length}`,'course-tab','data-id="learn"')}<div class="player-body"><div class="player-col wide"><span class="eyebrow">${d.professora?safe(d.professora.titulo)+' · você controla o ritmo':'Execução real · você controla o ritmo'}</span><h1 class="display">${d.system?'Acompanhe o sistema':'Siga as aproximações'}</h1><div class="sim-stage">${stage}</div><div class="step-explain"><h3>${row.i===0&&!d.system?'Condições iniciais':`Registro ${i+1} de ${r.iterations.length}`}</h3><p>${safe(row.detail)}</p>${info}<p class="fine">${note}</p></div></div></div><div class="player-bar"><div class="player-bar-inner"><div class="sim-controls">${btn('←','sim-prev','ghost round',`aria-label="Passo anterior" ${i===0?'disabled':''}`)}<input aria-label="Passo da simulação" id="sim-range" type="range" min="0" max="${r.iterations.length-1}" value="${i}">${btn('→','sim-next','ghost round',`aria-label="Próximo passo" ${i===r.iterations.length-1?'disabled':''}`)}</div><div class="answer-actions">${btn((worldOpen(s.method)?'Começar a praticar ':'Voltar à trilha ')+icon('arrow'),'sim-done','primary')}</div></div></div></div>`;}
function practice(){const id=`c:${s.method}:${s.q}`,task=C.TASKS[s.method][s.q],l=s.q<4?0:s.q<8?1:2;return `<div class="player">${playerTop(levelSegs(),`Nível ${l+1}: etapa ${s.q%4+1} de 4`,'course-tab','data-id="learn"')}<div class="player-body"><div class="player-col"><span class="eyebrow">Nível ${l+1} · ${C.LEVELS[s.q]}</span><p class="coach">${safe(C.COACH[s.method][s.q]||'Agora vá além da fórmula: pense nas condições, no erro e em como validar o resultado.')}</p>${question(task,id,'next-course')}</div></div></div>`;}
function course(){if(s.tab==='intro')return introPlayer();if(s.tab==='simulate')return simulation();if(s.tab==='practice')return practice();return courseOverview();}
function taskFor(id){const a=id.split(':');if(a[0]==='c')return C.TASKS[a[1]][+a[2]];if(a[0]==='a')return C.ARENA[+a[1]];return C.CASES.find(c=>c.id===a[1]).tasks[+a[2]];}
function currentId(){return s.page==='review'?s.reviewId:s.page==='case'?`p:${s.caseId}:${s.caseQ}`:`c:${s.method}:${s.q}`;}
function question(task,id,nextAction){const completed=p.completed[id];let opts=task.options?.map((v,i)=>({v,i}));if(opts){const shift=[...id].reduce((n,c)=>n+c.charCodeAt(0),0)%opts.length;opts=opts.slice(shift).concat(opts.slice(0,shift));}const reward=id.startsWith('p:')?'+40 XP':id.startsWith('a:')?'+30 XP':'+20 XP',fb=s.feedback;
 return `<form id="quiz-form" class="quiz" data-id="${id}"><div class="quiz-meta">${tag(task.type==='choice'?'Raciocínio':'Aplicação numérica')}${completed?tag('✓ Concluída '+stars(completed.stars),'green'):tag(reward,'xp')}</div><h2 class="quiz-q">${safe(task.q.replace('DESAFIO FINAL: ',''))}</h2>${opts?`<div class="choices" role="group" aria-label="Alternativas">${opts.map((o,j)=>`<button type="button" class="choice ${s.selected===o.i?'selected':''}" data-act="select" data-index="${o.i}" aria-pressed="${s.selected===o.i}"><span class="choice-key">${String.fromCharCode(65+j)}</span><span>${safe(o.v)}</span></button>`).join('')}</div>`:`<label class="answer-label" for="answer">Seu resultado</label><div class="answer-line"><input id="answer" type="text" inputmode="decimal" autocomplete="off" placeholder="Ex.: 1,416667 ou 17/12" value="${safe(s.answer)}"><span>Use ao menos 4 casas decimais quando necessário. Frações como 17/12 também valem.</span></div>`}
 ${s.hint?`<div class="hint-box"><b>Dica.</b> ${safe(task.hint||task.wrong||'Identifique os dados, escolha a fórmula e calcule cada termo antes de substituir.')}</div>`:''}
 <div class="player-bar ${fb?(fb.ok?'is-ok':'is-bad'):''}"><div class="player-bar-inner">${fb?`<div class="sheet-msg" role="status"><b>${fb.ok?'Correto!':'Ainda não.'}</b><span>${safe(fb.message.replace(/^Correto\.\s*/,''))}</span></div>`:`<span class="bar-count">${completed?'Refazer melhora as estrelas; o XP é recebido uma vez.':'Sem cronômetro. Pedir dica também faz parte.'}</span>`}<div class="answer-actions">${fb?.ok?btn('Continuar '+icon('arrow'),nextAction,'primary'):`${btn(s.hint?'Dica aberta':'Dica','hint','ghost',s.hint?'disabled':'')}<button class="btn primary" type="submit" id="check-btn">${fb?'Tentar de novo':'Conferir'}</button>`}</div></div></div></form>`;}

